public class OrderProcessorTest {
    // ANTI-PATTERN: Over-mocking value objects, domain logic, and collaborators
    @Test
    public void testProcessOrder_OverMocked() {
        OrderRepository orderRepo = mock(OrderRepository.class);
        Order order = mock(Order.class);
        TaxCalculator taxCalc = mock(TaxCalculator.class);
        DiscountPolicy discountPolicy = mock(DiscountPolicy.class);

        when(orderRepo.findById(1L)).thenReturn(order);
        when(order.getSubtotal()).thenReturn(BigDecimal.valueOf(100.00));
        when(taxCalc.calculate(any())).thenReturn(BigDecimal.valueOf(10.00));
        when(discountPolicy.apply(any())).thenReturn(BigDecimal.valueOf(5.00));

        OrderProcessor processor = new OrderProcessor(orderRepo, taxCalc, discountPolicy);
        BigDecimal finalTotal = processor.process(1L);

        assertEquals(BigDecimal.valueOf(105.00), finalTotal);
        verify(orderRepo).findById(1L);
        verify(order).getSubtotal();
    }

    // CORRECT: Real value objects and pure collaborators; mock only boundary IO
    @Test
    public void testProcessOrder_Proper() {
        OrderRepository orderRepo = mock(OrderRepository.class);
        Order realOrder = new Order(1L, BigDecimal.valueOf(100.00), CustomerType.REGULAR);

        when(orderRepo.findById(1L)).thenReturn(realOrder);

        // Using real TaxCalculator and DiscountPolicy implementations
        OrderProcessor processor = new OrderProcessor(orderRepo, new StandardTaxCalculator(), new StandardDiscountPolicy());
        BigDecimal finalTotal = processor.process(1L);

        assertEquals(BigDecimal.valueOf(105.00), finalTotal);
    }
}
